# -*- coding: utf-8 -*-
"""第1章 导论"""
from content_helpers import c, cc, R, BASE, NUMI06, NUMI23, LOSS06, LOSS23, ACE06, ACE23, SEG06, SEG23, pct


def blocks():
    B = []
    A = B.append
    A({'h1': '第1章  导论'})

    # ---------------- 1.1 研究背景与问题提出 ----------------
    A({'h2': '1.1  研究背景与问题提出'})
    A({'p': '建设全国统一大市场，是构建高水平社会主义市场经济体制的基础性工程，也是畅通国内大循环、构建新发展格局、推进中国式现代化的内在要求。2022年4月，'
          f'{c("cpc2022", paren=False)}正式发布，明确提出要"加快建设高效规范、公平竞争、充分开放的全国统一大市场，全面推动我国市场由大到强转变"，并系统部署了强化市场基础制度规则统一、'
          '推进市场设施高标准联通、打造统一的要素和资源市场、推进商品和服务市场高水平统一、推进市场监管公平统一等重点任务。2024年7月，党的二十届三中全会进一步将"构建全国统一大市场"'
          f'列为完善社会主义市场经济体制的重大改革举措，强调"规范地方招商引资法规制度，严禁违法违规给予政策优惠行为"{c("cpc2024plenum")}。2025年初，'
          f'{c("ndrc2025guide", paren=False)}以"应当做、不得做、鼓励做"三类清单的形式，将统一大市场建设从原则要求推向可操作、可考核的实施阶段。一个覆盖14亿多人口、'
          '超大规模的统一市场，正在成为中国参与国际竞争、塑造新竞争优势的战略性资源。'})
    A({'h3': '1.1.1  从高速增长阶段转向高质量发展阶段：新发展格局的战略召唤'})
    A({'p': '党的十八大以来，中国经济发展的阶段性特征发生深刻变化，已由高速增长阶段转向高质量发展阶段。从总量看，国内生产总值由2012年的51.93万亿元增长到2024年的134.9万亿元，稳居世界第二大经济体，经济实力、科技实力、综合国力跃上新台阶；但从增速看，经济增长中枢由2012年的7.8%回落至2024年的5.0%左右，"增速换挡"成为新常态。与此同时，支撑高速增长的传统条件正在发生趋势性改变：劳动年龄人口达峰后逐步回落，人口红利加快消退，资本深化的边际报酬递减，土地、能源与生态环境约束不断趋紧。'
          f'在这一背景下，单纯依靠要素规模扩张驱动增长的模式已难以为继，通过优化资源配置、提高全要素生产率培育增长新动能，成为跨越关口、实现高质量发展的必由之路{c("cai2021")}。'})
    A({'p': '在高质量发展阶段，超大规模市场是中国最为独特而突出的比较优势。中国拥有14亿多人口、4亿以上并持续扩大的中等收入群体，2024年底经营主体总量达到1.89亿户（其中企业6086.7万户），是全球最具成长性的统一市场。超大规模市场优势的经济学含义是双重的：在需求侧，它意味着广阔而多层次的市场空间，能够为规模经济、范围经济与创新试错提供足够纵深；在供给侧，它意味着可以在更大范围内深化分工、细化专业化，形成完整且富有韧性的产业链供应链体系。'
          f'然而，市场规模优势能否转化为现实竞争力，关键取决于市场是否统一——如果市场被行政边界人为切割为相互分割的"小市场"，规模优势就会在分割中被消解{c("liu2021")}。正因如此，将超大规模市场优势转化为统一大市场优势，成为构建新发展格局、塑造国际竞争新优势的关键一环。'})
    A({'p': '从战略全局看，加快建设全国统一大市场是构建新发展格局的基础支撑。构建以国内大循环为主体、国内国际双循环相互促进的新发展格局，要求以统一大市场畅通生产、分配、流通、消费各环节，实现国民经济的良性循环。近年来，一系列结构性变化既凸显了统一大市场建设的紧迫性，也为其提供了现实条件：一是数字经济快速发展，2023年数字经济规模达到53.9万亿元，占国内生产总值比重升至42.8%，数字技术显著降低了跨区域交易的信息成本与匹配成本，为打破市场分割提供了新的技术手段；二是人口大规模流动，第七次全国人口普查显示全国流动人口达3.76亿，其中跨省流动1.25亿，客观上要求破除户籍等制度壁垒；三是城镇化持续推进，常住人口城镇化率由2012年的52.57%提高到2024年的67.00%，城乡、区域间要素流动日益频繁。把握这些趋势、顺势而为，正是统一大市场建设的时代要求。'})
    A({'h3': '1.1.2  要素市场化配置改革的深化：从商品市场统一走向要素市场统一'})
    A({'p': '建设全国统一大市场，本质上是市场化改革在更高层次、更广范围上的系统集成，其中要素市场化配置改革居于核心地位。'
          f'2020年4月，{c("cpc2020factor", paren=False)}发布，首次将数据与土地、劳动力、资本、技术并列为五大生产要素，明确提出健全要素由市场评价贡献、按贡献决定报酬的机制。这一改革指向一个长期存在的结构性问题：相较于商品和服务市场，中国要素市场的市场化程度明显滞后，要素价格形成与流动配置仍受到较多行政干预{c("fan2021")}。破除要素跨区域流动的体制机制障碍，让各类要素在更大范围内自由流动、优化组合，正是统一大市场建设最具含金量、也最为艰巨的任务。'})
    A({'p': '从演进历程看，中国的市场一体化呈现"商品市场先行、要素市场滞后"的非对称特征。就商品市场而言，随着统一开放的现代流通体系逐步建立，以相对价格法测度的商品市场分割程度长期趋于下降'
          f'{cc("gui2006","sheng2011")}；本书测算的市场分割指数也由2006年的{SEG06:.3f}降至2023年的{SEG23:.3f}，商品市场一体化水平稳步提升。然而，要素市场的一体化进程要复杂和缓慢得多：户籍制度对劳动力自由迁徙的约束、金融资源配置的属地化倾向、建设用地指标的行政化分配以及数据要素跨区域流通的壁垒，使得要素市场分割更具刚性、更难破除。正是这种商品市场与要素市场整合程度的不对称，构成了本书聚焦"要素市场行政性分割"的现实起点。'})
    A({'p': '从制度演进看，破除市场分割、健全要素市场化配置的努力持续深化，形成了层层递进的政策序列。'
          f'2020年，中央将数据纳入生产要素、系统部署要素市场化配置改革；2022年，{c("data20", paren=False)}进一步就数据产权、流通交易、收益分配等作出制度安排，2023年组建国家数据局，加快培育全国一体化数据要素市场；与此同时，全国统一大市场建设从2022年《意见》的原则部署，经二十届三中全会的改革定位，到《建设指引》的清单化落实，逐步由顶层设计走向操作实施。这一政策序列表明，统一大市场建设是一项持续推进、系统集成的长期工程，其重心正从商品市场加速拓展至要素市场，尤其是数据等新型要素市场。'})
    A({'h3': '1.1.3  地方保护与市场分割：现实表现、制度根源与经济危害'})
    A({'p': '然而，从"市场大"走向"市场强"、从"分割"走向"统一"，绝非一蹴而就。改革开放以来，在财政分权和以经济增长为核心的地方官员激励机制驱动下，'
          f'地方政府具有强烈的动机通过行政手段保护本地市场、扶持本地企业，由此形成了广受关注的"诸侯经济"与国内市场分割现象{cc("zhou2007","yin2001")}。这种分割不仅体现在'
          '商品市场上的地方保护、市场准入歧视，更深刻地体现在劳动力、资本、土地、技术与数据等要素市场上的行政性壁垒——户籍制度对劳动力自由流动的限制、金融资源配置的属地化倾向、'
          f'建设用地指标的行政化分配、数据要素的地区"孤岛化"等，共同构成了要素跨区域高效配置的制度性摩擦{cc("lu2009","btz2013")}。'})
    A({'p': '从现实表现看，地方保护和市场分割形式多样、隐蔽性强。在商品市场，它表现为对外地商品设置歧视性的技术标准与检验检疫要求，在政府采购和招标投标中变相排斥外地经营者，以及通过财政补贴、税收返还扶持本地企业等；在要素市场，则表现为对外来劳动者的就业与公共服务歧视、信贷资源的本地化配置、土地要素向本地关联主体倾斜等。'
          f'以汽车市场为例，{c("barwick2021", paren=False)}发现地方政府对本地车企的保护显著扭曲了市场结构、抬高了消费者成本、降低了社会总福利。这些行为的深层根源在于"中国式分权"下的激励结构：财政分权赋予地方相对独立的经济利益，以增长为核心的政绩考核则强化了地方政府"为增长而竞争"的动机{cc("zhou2007","fu2007")}，二者叠加使地方政府倾向于以行政手段保护本地税基与就业，从而内生出市场分割。'})
    A({'p': '进一步分维度看，要素市场的行政性分割在不同要素上各具形态：在劳动力市场，户籍制度及其捆绑的教育、医疗、社保等公共服务差异，抬高了劳动力跨地区、跨城乡流动的隐性成本，抑制了人力资源的优化配置；在资本市场，金融资源配置存在明显的属地化倾向，地方融资平台与本地国有企业更易获得信贷，民营和外地企业则常受挤出；在土地市场，建设用地指标由行政层层分解、区域间难以有偿调剂，导致土地要素配置与人口、产业的空间流向相背离；在技术与数据市场，创新要素的跨区域流动仍面临体制壁垒，数据的"孤岛化""地方化"则制约了数据要素价值的充分释放。这些分割相互交织，共同抬高了要素跨区域配置的制度性成本，也使得统一大市场建设呈现出多维度、系统性推进的复杂性。'})
    A({'p': '市场分割的经济后果是深远的。一方面，它割裂了统一市场的规模优势，抑制了分工深化与规模经济的发挥，使超大规模市场难以转化为现实的竞争力；'
          f'另一方面，更为关键的是，它扭曲了要素价格信号，阻碍了要素由低效率部门和地区流向高效率部门和地区，造成了大范围、系统性的资源错配与全要素生产率（TFP）损失{cc("hk2009","yu2022")}。'
          f'{c("hk2009", paren=False)}的经典研究表明，如果将中国制造业企业间的资源错配程度降低至美国的水平，中国制造业的全要素生产率可提升约30%~50%；这一"错配红利"的量级，'
          '足以构成中国经济在增速换挡、结构调整背景下最重要的效率来源之一。当前，中国经济正处在从高速增长转向高质量发展、新旧动能加快转换的关键阶段，'
          '在传统要素投入边际报酬递减、人口红利逐步消退的约束下，通过破除市场分割、优化要素配置来释放全要素生产率增长潜力，已成为一项紧迫而重大的现实课题。'})
    A({'p': '市场分割的危害还体现在更广的层面。其一，地方保护催生低水平重复建设与产能过剩，各地竞相布局"大而全""小而全"的产业体系，削弱了基于比较优势的地区分工，造成资源的重复投入与闲置'
          f'{cc("lu2004","han2014")}。其二，市场分割弱化了优胜劣汰的竞争机制，使低效率企业得以在本地保护下存续，抑制了资源向高效率企业集中，延缓了产业升级。其三，分割还会带来环境与福利的负外部性，地方为保护本地企业而放松环境规制，可能加剧污染并降低整体社会福利{cc("songml2016","lvyue2021")}。凡此种种表明，市场分割不仅是效率问题，更关乎发展方式转变与高质量发展全局。'})
    A({'p': '针对中国的一系列研究进一步量化了市场分割与要素错配的效率代价。'
          f'{c("zheng2003", paren=False)}较早估计了地方分割造成的效率损失；{c("yu2022", paren=False)}从国内大循环视角测算发现，区域市场分割带来了可观的效率损失；{c("btz2013", paren=False)}则强调，跨地区、跨部门的要素市场扭曲是中国全要素生产率损失的重要来源。与这些研究相呼应，本书基于要素错配核算得到的反事实测算显示，若彻底消除要素错配，全要素生产率的可提升幅度由2006年的约{LOSS06:.0f}%降至2023年的约{LOSS23:.0f}%——错配程度虽持续改善，但截至样本期末，要素错配仍使中国潜在全要素生产率损失约四分之一，其量级与经典研究的估计相当{c("hk2009")}。这表明，破除市场分割、优化要素配置所蕴含的"改革红利"依然十分可观，构成中国经济提质增效的重要潜在来源。'})
    A({'h3': '1.1.4  研究问题的提出'})
    A({'p': '正是在这一背景下，本书试图回答的核心问题是：**全国统一大市场建设，究竟如何影响要素配置效率？其作用机制、异质性特征与经济效应如何？又应通过怎样的改革路径加以推进？**'
          '围绕这一核心问题，本书进一步细分为以下四个相互关联的子问题：第一，如何在理论上刻画中国式市场分割的本质，并构建统一大市场建设影响要素配置效率的分析框架？'
          '第二，如何科学测度中国各地区统一大市场建设的水平及其时空演变？第三，统一大市场建设对要素配置效率的影响在方向、大小、机制和异质性上呈现怎样的经验规律？'
          '第四，如何评估其对全要素生产率、创新与区域协调发展的拓展效应，并据此提出兼具理论逻辑与现实可行性的政策建议？'})
    A({'p': '这四个子问题环环相扣、层层深入：理论刻画是测度与识别的前提，科学测度是因果推断的基础，机制检验是理解效应来源的关键，效应拓展与政策建议则是研究的落脚点。回答这些问题，既需要构建能够容纳商品与要素双重摩擦的分析框架，也需要建立可靠的测度体系并运用严谨的因果识别方法，还需要在实证发现与现实约束之间寻求政策上的平衡。本书正是围绕这一问题链条循序展开，力求在学理与实践两个层面提供系统的解答。'})

    # ---------------- 1.2 研究意义 ----------------
    A({'h2': '1.2  研究意义'})
    A({'h3': '1.2.1  理论意义'})
    A({'p': '第一，深化了对中国式市场分割本质的理论认识。既有文献多沿用源于国际贸易的"冰山成本"思路，聚焦于商品市场的价格分割'
          f'{cc("young2000","gui2006")}，而对要素市场分割的制度根源及其配置效率后果缺乏系统的理论刻画。本书提出"要素市场的行政性分割"这一概念，'
          '将劳动力、资本、土地、技术与数据等要素市场因行政边界产生的制度性流动壁垒纳入统一分析框架，并以"制度性配置楔子"及其跨地区离散度刻画其效率后果，'
          '有助于从中国实践中提炼具有本土解释力的分析工具。'})
    A({'p': '第二，拓展了资源错配与经济增长理论的空间维度。本书构建一个包含商品市场冰山成本与要素市场流动壁垒的多地区—多部门空间一般均衡模型，'
          f'在{c("hk2009", paren=False)}与{c("btz2013", paren=False)}的分析传统基础上，将统一大市场建设内生化为对两类摩擦的同时削减，'
          '推导出总量全要素生产率与要素楔子离散度之间的解析关系，并揭示商品市场整合与要素市场整合之间的互补性，为理解统一大市场的效率红利提供了微观机制基础。'})
    A({'p': '第三，为统一大市场建设水平的量化研究提供了新的测度方案。本书从商品、劳动力、资本、土地、技术与数据、制度环境六个维度构建"全国统一大市场建设指数"（NUMI），'
          '弥补了以往仅以单一价格分割指数或市场化总指数刻画市场一体化的不足，为后续实证研究和政策评估提供了可复用的测度基础。'})
    A({'p': '第四，丰富了市场一体化经济效应的机制解释。既有研究多关注市场一体化对经济增长、企业生产率的总体影响'
          f'{cc("huangzl2020","bianyc2021")}，而对其内在作用机制的系统刻画相对不足。本书从要素流动、竞争淘汰、创新激励与规模专业化四条渠道搭建统一的机制分析框架，并论证统一大市场建设的配置效率红利随初始分割程度递增这一异质性命题，既深化了对"为什么统一大市场能够提升配置效率"的理论理解，也为经验检验提供了可操作的机制识别思路。'})
    A({'p': '第五，为空间经济学与发展经济学的对话提供了中国经验。市场分割、要素错配与经济增长的关系，是空间经济学、发展经济学与转型经济学共同关注的重大议题'
          f'{cc("krugman1991","rr2017")}。本书立足中国"行政区经济"的独特情境，将制度性市场分割纳入空间一般均衡框架，既回应了国际前沿关于"错配来源"的争论，也以超大规模转型经济体的证据丰富了相关理论，有助于提升中国经济学研究的国际对话能力。'})
    A({'h3': '1.2.2  现实意义'})
    A({'p': '第一，服务于构建高水平社会主义市场经济体制的战略需要。破除地方保护和市场分割、健全要素市场化配置体制机制，是全面深化改革的重点领域。'
          '本书通过测度各地区统一大市场建设的短板与差距，识别要素错配最严重的领域和地区，可为分类施策、精准发力提供经验依据。'})
    A({'p': '第二，服务于畅通国内大循环、构建新发展格局的迫切要求。国内统一大市场是国内大循环的载体和基础。本书量化评估统一大市场建设对要素配置效率、'
          '全要素生产率和区域协调发展的贡献，有助于从"效率"和"协调"双重视角，论证加快建设全国统一大市场对畅通经济循环、增强发展韧性的重要作用。'})
    A({'p': '第三，为破解"统一"与"竞争"、"全国一盘棋"与"地方积极性"之间的现实张力提供政策思路。本书在识别地方保护制度根源的基础上，'
          '从破除壁垒、要素市场化改革、统一制度规则、设施联通和激励相容五个方面提出系统性改革方案，力求兼顾顶层设计与地方激励，具有较强的现实针对性。'})
    A({'p': '第四，服务于促进区域协调发展与扎实推进共同富裕的战略目标。要素的自由流动与合理配置，是缩小区域差距、推进基本公共服务均等化的重要前提。2024年，人均GDP最高的北京超过22万元、上海超过21万元，而最低省份约5万元，省际极差仍在4倍以上；这种区域差距在很大程度上与要素流动不畅、市场分割导致的资源错配相关。本书从要素配置效率视角揭示统一大市场建设对区域协调发展的作用，可为通过市场一体化促进区域均衡发展、夯实共同富裕的物质基础提供决策参考。'})
    A({'p': '第五，为全国统一大市场建设的政策评估提供量化工具与经验支撑。'
          f'随着{c("ndrc2025guide", paren=False)}以"应当做、不得做、鼓励做"三类清单推动建设进入可操作、可考核阶段，科学评估各地区建设进展与成效的需求日益迫切。本书构建的全国统一大市场建设指数及配套的效率损失核算方法，可作为监测区域建设水平、识别薄弱环节、评估政策效果的分析工具，具有直接的政策应用价值。'})
    A({'p': '第六，有助于增强产业链供应链的自主可控与安全韧性。面对外部环境不确定性上升，超大规模统一市场是抵御外部冲击、保障经济安全的重要依托。统一大市场通过畅通国内循环、稳定市场预期，能够为关键产业的自主创新和进口替代提供广阔的需求空间与规模支撑，从而增强产业链供应链的抗风险能力。本书对统一大市场建设效率效应的评估，也从一个侧面为理解其在保障经济安全、支撑高水平科技自立自强中的作用提供了参考。'})

    # ---------------- 1.3 核心概念界定 ----------------
    A({'h2': '1.3  核心概念界定'})
    A({'p': '为避免歧义，本节先行界定贯穿全书的若干核心概念，其严格的数理定义将在第4章给出。'})
    A({'p': '**全国统一大市场**。指在全国范围内，商品和要素能够按照统一的规则和标准自由流动、公平交易，价格主要由供求关系决定，'
          '不存在人为的行政壁垒和地区歧视的市场体系。其内涵可概括为"五统一"：市场基础制度规则统一、市场设施高标准联通、要素和资源市场统一、'
          '商品和服务市场高水平统一、市场监管公平统一。与之相对的是"市场分割"，即由行政力量人为造成的地区间市场壁垒。'})
    A({'p': '需要辨析的是，"统一大市场"并不等于"单一均质市场"，更不意味着取消竞争或搞"一刀切"式的行政整合。国际经验表明，大型经济体普遍以制度化方式维护市场统一：美国以宪法"州际贸易条款"限制各州设置贸易壁垒，欧盟以"商品、人员、服务、资本"四项自由流动构建统一市场。'
          f'与之相比，中国的统一大市场建设是在单一制国家结构和社会主义市场经济体制下推进的，其独特之处在于既要打破行政性分割、维护公平竞争，又要充分发挥中央和地方两个积极性，处理好"有为政府"与"有效市场"的关系{cc("chenyx2019","ye2022")}。因此，本书所讨论的"统一"，是规则统一、要素畅通意义上的统一，而非否定地区特色与市场竞争的绝对同质化。'})
    A({'p': '**要素市场的行政性分割**。本书提出的核心概念，指劳动力、资本、土地、技术与数据等生产要素，因户籍管制、金融属地化、用地指标行政配置、'
          '数据地区封锁等制度安排，在跨行政区流动时面临的非市场化壁垒。它区别于由自然地理和运输成本导致的"自然分割"，其根源在于制度而非技术，'
          '因而可以通过改革加以消除，这也正是统一大市场建设的着力点。'})
    A({'p': '这一概念与国际文献中的"要素市场扭曲"（factor market distortions）既有联系又有区别。'
          f'国际研究多在企业异质性框架下将要素错配抽象为企业面临的"税收楔子"，并不特别追究其制度来源{cc("hk2009","rr2008")}；而中国的要素市场分割具有鲜明的"行政边界"特征——同一要素跨越省界、市界时面临的壁垒，往往显著高于其在行政区内部流动的成本{cc("btz2013","tz2019")}。本书强调"行政性"这一限定词，正是为了突出中国式要素市场分割的制度根源与空间属性，将其与源于自然地理、运输成本的"自然分割"相区别，从而把改革的着力点锁定在可通过制度变革加以消除的部分。'})
    A({'p': '**制度性配置楔子**。借鉴资源错配文献的"楔子"（wedge）概念，本书用制度性配置楔子刻画要素边际收益产品与其机会成本之间由制度性分割造成的偏离。'
          '当要素市场完全一体化时，同质要素在不同地区、部门的边际收益产品应趋于相等；楔子越大、跨地区离散度越高，意味着错配越严重、配置效率越低。'})
    A({'p': '"楔子"（wedge）方法是资源错配文献的核心分析工具。其基本思想是，将各种难以直接观测的制度性、政策性扭曲统一表示为在要素价格或产品价格上打入的"楔子"，再通过要素边际收益产品的离散程度反推错配的严重程度'
          f'{cc("chen2011","gong2013")}。在完全竞争且无扭曲的理想状态下，同质要素在不同使用者之间的边际收益产品应当相等；现实中观测到的边际收益产品离散度越大，意味着配置越偏离最优。本书的创新在于为楔子赋予明确的制度含义，将其跨地区离散度与统一大市场建设水平直接关联，从而把抽象的错配核算与具体的市场分割改革连接起来。'})
    A({'p': '**要素配置效率**。指要素在地区、部门、企业之间的配置使总产出（或社会福利）达到或接近最优的程度。'
          '本书以"1减去标准化的要素错配指数"度量地区层面的要素配置效率，并用其与全要素生产率的联系刻画配置效率对经济增长的贡献。'})
    A({'p': '需要区分配置效率（allocative efficiency）与技术效率（technical efficiency）：前者关注既定要素总量在不同主体间的分配是否使总产出最大化，后者关注既定投入下产出是否达到技术前沿。市场分割主要通过扭曲要素的空间与部门配置来损害配置效率，进而拉低总量全要素生产率；本书的分析重心在配置效率，同时关注配置改善通过竞争与创新对技术效率的间接提升。'
          f'需要说明的是，配置效率的严格测度依赖一系列假设，不同的生产函数设定与错配识别策略可能得到量级不同的估计{cc("gong2013","yang2015")}，因此本书在测度时将报告多种设定下的结果以检验稳健性。'})
    A({'p': '**全要素生产率（TFP）**。指在剔除资本、劳动等要素投入贡献后，由技术进步、效率改善与资源配置优化等共同决定的产出增长部分，是衡量经济增长质量与集约化程度的核心指标。在本书的分析框架中，全要素生产率既包含反映技术水平的"纯技术"成分，也包含反映资源配置状况的"配置"成分；统一大市场建设主要通过改善后者、并经由竞争与创新带动前者，来提升总量全要素生产率。厘清这一分解，有助于准确理解统一大市场建设影响经济增长的作用路径。'})
    A({'p': '**市场分割指数与相对价格法**。为从数据上刻画市场分割程度，本书沿用国内外广泛采用的相对价格法：其基本逻辑是，若两地市场充分整合，同类商品的相对价格在套利作用下应趋于收敛，相对价格的波动方差越大，表明市场分割越严重'
          f'{cc("gui2006","poncet2005")}。这一方法源于国际贸易中的"冰山成本"与"一价定律"思想，经本土化改造后成为测度中国国内市场分割的主流工具{c("zhanghao2020")}。需要指出的是，相对价格法主要捕捉商品市场分割，对要素市场分割的刻画能力有限；这也正是本书在指数构建中引入劳动力、资本、土地、技术与数据等要素维度、以弥补单一价格法不足的原因所在。'})

    # ---------------- 1.4 研究思路、方法与数据 ----------------
    A({'h2': '1.4  研究思路、方法与数据'})
    A({'h3': '1.4.1  研究思路与技术路线'})
    A({'p': '本书遵循"提出问题—构建理论—测度识别—检验机制—政策应用"的研究思路，力求"顶天立地"：一方面，从中国统一大市场建设的实践中提炼新概念、'
          '构建本土化理论并进行数理刻画（顶天）；另一方面，以严谨的测度和识别检验理论、回应现实关切，为破解地方保护、要素错配等难点问题提供政策指引（立地）。'
          '总体研究思路与技术路线如图1.1所示。'})
    A({'fig': 'figs/fig1_1.png', 'caption': '图1.1  本书研究思路与技术路线图', 'width_cm': 13.5})
    A({'p': '具体而言，全书的逻辑链条可概括为五个相互衔接的环节：一是从中国统一大市场建设的实践中提炼"要素市场行政性分割"这一核心问题；二是构建包含商品与要素双重摩擦的空间一般均衡模型，推导可检验命题；三是从六个维度测度统一大市场建设水平并核算要素错配损失，为实证提供变量基础；四是运用双向固定效应、工具变量与双重差分等方法识别因果效应、检验机制与异质性；五是在此基础上提炼结论、提出改革建议。这一"提出问题—构建理论—测度识别—检验机制—政策应用"的闭环，既保证了研究的逻辑自洽，也确保了理论探讨与现实关切的有机统一。'})
    A({'h3': '1.4.2  研究方法'})
    A({'p': '在研究方法上，本书综合运用理论建模与实证检验相结合、规范分析与实证分析相结合、定性分析与定量分析相结合的方法。'
          '具体包括：（1）空间一般均衡建模与数理推导，用于刻画统一大市场建设影响要素配置效率的理论机制并提出可检验命题；'
          '（2）综合评价方法，用于构建全国统一大市场建设指数（NUMI）并刻画其时空演变；（3）生产率与错配核算方法，用于估计要素错配程度及其造成的效率损失；'
          '（4）面板计量方法，包括双向固定效应模型、工具变量法和多期双重差分法，用于识别统一大市场建设对要素配置效率的因果效应及其机制与异质性。以下分别说明各方法的适用性与实施要点。'})
    A({'p': '**第一，空间一般均衡建模与数理推导。** 本书借鉴资源错配与空间经济学的分析传统'
          f'{cc("hk2009","btz2013","tz2019")}，构建一个包含商品市场冰山成本与要素市场流动壁垒的多地区—多部门空间一般均衡模型。该方法的适用性在于：一方面，它能够在统一的均衡框架内同时刻画商品流动与要素流动，揭示两类摩擦对总量产出与全要素生产率的影响；另一方面，通过比较静态分析可以推导出可检验的理论命题，为后续实证研究提供明确的假说与识别对象。模型求解采用数值校准与解析推导相结合的方式，关键参数（如替代弹性、要素份额）取值参考既有文献的经验估计，并通过敏感性分析考察结论的稳健性。'})
    A({'p': '**第二，综合评价与指数构建方法。** 为刻画统一大市场建设水平，本书从商品、劳动力、资本、土地、技术与数据、制度环境六个维度选取指标，采用主观赋权与客观赋权相结合的方式合成全国统一大市场建设指数（NUMI）。'
          f'相较于以往仅用单一价格分割指数{c("gui2006")}或市场化总指数{c("fan2021")}刻画市场一体化的做法，多维复合指数能够更全面地反映统一大市场建设的结构性特征。在指标处理上，本书对原始指标进行方向一致化与标准化处理，并通过分维度得分考察商品市场与不同要素市场一体化进程的非同步性，从而识别各地区建设的短板所在。'})
    A({'p': '**第三，生产率与要素错配核算方法。** 本书沿用要素边际收益产品离散度的思路测度要素错配，并据以估计错配造成的全要素生产率损失'
          f'{cc("chen2011","gong2013")}。该方法的适用性在于，它无需直接观测各种具体扭曲，而是从可观测的产出与要素投入数据出发反推错配程度，与本书"制度性配置楔子"的理论刻画相互对应。核算中本书分别测度资本错配与劳动力错配，并进行反事实模拟，以评估消除错配对总量全要素生产率的提升空间，同时报告不同生产函数设定下的结果以检验稳健性。'})
    A({'p': '**第四，面板计量与因果识别方法。** 为识别统一大市场建设对要素配置效率的因果效应，本书综合运用多种识别策略：以双向固定效应模型控制地区与时间层面不可观测的异质性，作为基准估计；针对可能存在的反向因果与遗漏变量问题，选取历史驿道、明清行政边界、地形起伏度等外生变量以及Bartik份额移动份额工具变量进行工具变量估计；并以2022年《意见》出台为准自然实验，采用多期双重差分法进行识别，同时使用异质性稳健的估计量以应对交错处理下传统双重差分可能产生的偏误。多种识别策略相互印证，有助于增强因果推断的可信度。'})
    A({'h3': '1.4.3  样本、数据来源与变量处理'})
    A({'p': '在数据方面，本书以中国31个省级行政区（不含港澳台）2006—2023年的面板数据为主要分析对象，'
          '数据来源包括《中国统计年鉴》、各省（区、市）统计年鉴、《中国区域经济统计年鉴》、国家统计局分省年度数据、中国工业企业数据库、'
          '中国信息通信研究院《中国数字经济发展研究报告》以及相关政府公开文件等。需要说明的是，用于计量识别的省级面板在公开统计口径的基础上，'
          '结合既有文献对市场分割指数、要素错配等关键变量的测度方法进行了整理与校准，其用途在于展示测度与识别方法、揭示总体规律；'
          '在正式出版或政策评估中，建议进一步接入企业层面的原始微观数据以提升估计精度。'})
    A({'p': '在变量测度上，被解释变量要素配置效率由标准化的要素错配指数取补构造，核心解释变量为NUMI及其六个分维度指数；控制变量涵盖人均GDP（对数）、产业结构、城镇化率、数字经济发展、交通密度、财政分权、对外开放、人力资本与金融发展等（详见第七章）。为消除量纲影响并缓解异常值干扰，连续变量在必要时进行对数化与缩尾处理。需要再次强调的是，本书用于计量识别的省级面板系在公开统计与既有文献校准基础上整理而成，旨在完整呈现从理论建模、指标测度到因果识别的方法链条；正式发表或政策评估时应替换为经授权的企业层面原始微观数据，以进一步提升估计的精度与可信度。'})
    A({'p': '就统一大市场建设指数的分维度数据而言，商品市场维度主要依据各省分类商品价格指数以相对价格法测算；劳动力市场维度综合考虑跨地区流动、工资差异与户籍开放程度；资本市场维度反映信贷可得性与资本回报的地区离散度；土地市场维度刻画土地出让方式与地价形成的市场化程度；技术与数据市场维度反映技术交易活跃度、数字基础设施与数据流通条件；制度环境维度则综合公平竞争审查、行政审批效率与市场监管统一等信息。各维度指标的详细口径、来源与合成方法将在第五章集中说明，此处从略。'})
    A({'h3': '1.4.4  关键技术难点与应对'})
    A({'p': '在研究推进过程中，本书着力应对三个方面的技术难点。第一，市场分割与要素错配的"不可观测性"。制度性壁垒往往难以直接度量，本书通过"以离散度识别楔子"的思路，用可观测的价格离散度与要素回报离散度反推不可观测的制度性楔子，并以多维指数从正面刻画建设水平，两相对照、相互校验。第二，因果识别中的内生性。统一大市场建设与要素配置效率之间可能存在双向因果，且潜在遗漏变量众多；对此本书采用工具变量与准自然实验相结合的策略，并辅以安慰剂检验、平行趋势检验等稳健性分析。第三，测度口径与数据质量。要素市场一体化涉及劳动力、资本、土地、技术与数据等多个领域，指标口径不一、部分数据可得性较差；本书通过多来源交叉核对、分维度稳健性检验以及对关键变量的替代度量，尽可能降低测度误差对结论的影响。这些应对措施贯穿全书的测度与实证环节，构成理解后续章节结果的重要方法论前提。'})

    # ---------------- 1.5 研究内容与结构安排 ----------------
    A({'h2': '1.5  研究内容与结构安排'})
    A({'p': '全书除本章外，共分为九章，逻辑上可归为"理论—测度—实证—政策"四个板块。'})
    A({'p': '**第一板块：理论基础与分析框架（第2—4章）。** 第2章界定核心概念、系统梳理市场分割、资源错配与要素配置的相关文献，'
          '并阐明本书的理论基础与研究空间；第3章考察全国统一大市场建设的历史逻辑、制度演进与现实图景，以翔实的数据勾勒典型事实；'
          '第4章构建包含商品市场与要素市场双重摩擦的空间一般均衡模型，通过数理推导提出核心命题，奠定全书的理论基础。'})
    A({'p': '**第二板块：测度体系与效率损失（第5—6章）。** 第5章构建全国统一大市场建设指数（NUMI）及其六个分维度指标，刻画2006—2023年的时空演变格局；'
          '第6章测度劳动力、资本、土地等要素的错配程度，估计要素错配造成的全要素生产率损失。'})
    A({'p': '**第三板块：因果识别与机制检验（第7—9章）。** 第7章以双向固定效应模型为基础，识别统一大市场建设对要素配置效率的基准影响并进行稳健性检验；'
          '第8章从要素流动、竞争淘汰、创新激励等方面检验作用机制，并从区域、要素类型等维度考察异质性；第9章借助工具变量与多期双重差分法进行因果识别，'
          '并拓展考察统一大市场建设对全要素生产率、创新与区域协调发展的经济效应。'})
    A({'p': '**第四板块：结论与政策（第10章）。** 第10章总结全书主要结论，从破除地方保护、深化要素市场化改革、统一市场制度规则、'
          '推进设施联通、健全激励相容机制等方面提出政策建议，并指出研究不足与未来展望。'})
    A({'p': '从"理论—测度—实证—政策"的整体逻辑看，各章之间环环相扣、层层递进：理论板块提出"统一大市场建设→要素错配下降→配置效率与全要素生产率提升"的核心命题并给出数理刻画；测度板块为核心解释变量（NUMI）与被解释变量（要素配置效率、错配损失）提供可靠的量化基础；实证板块以严谨的因果识别检验理论命题并揭示机制与异质性；政策板块则将研究发现转化为可操作的改革建议，从而形成从学理探讨到现实关切的闭环。这一结构安排力求使全书既有理论深度，又有经验支撑与政策针对性。'})
    A({'p': '需要说明的是，上述各章在内容上各有侧重、在方法上前后照应：理论章为实证章提供命题与识别对象，测度章为实证章提供变量与事实基础，实证章为政策章提供经验依据，政策章则回应导论提出的核心问题。读者既可循章顺读以把握完整逻辑，也可根据关注点选择理论、测度、实证或政策板块重点研读。为便于阅读，各章大体以"引言—主体—小结"的结构展开，并在关键处以图表呈现核心结果。'})

    # ---------------- 1.6 主要创新与不足 ----------------
    A({'h2': '1.6  可能的创新与不足'})
    A({'p': '本书可能的创新之处主要体现在三个方面。**在概念与理论上**，提出"要素市场的行政性分割"与"制度性配置楔子"概念，'
          '构建了统一大市场建设影响要素配置效率的空间一般均衡分析框架，推导出总量全要素生产率与要素楔子离散度的解析关系，并揭示商品市场整合与要素市场整合的互补性，'
          '为理解中国式市场分割及其效率后果提供了本土化的理论工具。**在测度上**，构建了涵盖商品、劳动力、资本、土地、技术与数据、制度环境六维的全国统一大市场建设指数，'
          '相较以往单一维度的分割指数更为全面，并刻画了其时空演变与区域差异。**在经验证据上**，综合运用双向固定效应、工具变量与多期双重差分等方法，'
          '较为系统地识别了统一大市场建设影响要素配置效率的因果效应、作用机制与异质性，'
          f'发现统一大市场建设水平每提升一个标准差，要素配置效率显著提高，且其边际红利在初始分割程度较高的地区更大，为"命题3"提供了经验支持。'})
    A({'p': '此外，在研究视角与方法集成上，本书亦有若干新的尝试：一是坚持"商品市场—要素市场"并重、以要素市场为重点的分析视角，纠正以往市场一体化研究偏重商品市场的倾向；二是将规范的理论建模、系统的指数测度与多策略的因果识别有机结合，形成"理论命题—测度识别—机制检验"相互印证的完整证据链；三是把学术研究与政策评估相衔接，使本书的测度体系与主要结论能够直接服务于全国统一大市场建设的进展监测与成效评估。'})
    A({'p': '本书也存在一些不足。其一，受数据可得性限制，统一大市场建设指数的部分分维度指标以省级宏观数据为主，'
          '尚难充分捕捉市场分割在城市、行业乃至企业层面的微观异质性；其二，理论模型为突出核心机制进行了必要简化，'
          '对要素市场分割的动态调整、预期与政治经济学因素的刻画有待深化；其三，作为一项晚近的制度变革，全国统一大市场建设的中长期效应仍有待更长时间窗口的数据加以检验。'
          '这些不足也为后续研究留下了拓展空间。'})
    A({'p': '面向未来，至少有三个方向值得进一步拓展：其一，随着企业级、个体级微观数据和高频交易数据日益丰富，可在更细颗粒度上刻画市场分割与要素错配的微观机制；其二，可将数据要素市场、全国统一电力市场、全国碳排放权交易市场等新兴统一市场纳入分析，考察新型要素与新型市场对配置效率的影响；其三，可在开放经济框架下考察国内统一大市场与国际市场的互动，揭示统一大市场建设对畅通国内国际双循环、增强产业链供应链韧性的作用。这些拓展有望在本书搭建的分析框架上持续深化对"统一大市场—要素配置效率"这一重大命题的认识。'})
    A({'p': '总之，本章交代了研究的背景与问题、意义与概念、思路与方法、结构与创新，勾勒出全书的整体框架。作为逻辑起点，导论所提出的"统一大市场建设如何影响要素配置效率"这一核心问题，将在随后各章中被逐步展开、检验与回答。下一章将在系统梳理市场分割、资源错配与要素配置相关文献的基础上，进一步阐明本书的理论基础与研究空间，为理论框架的构建作好铺垫。'})
    return B
